def decimal_to_binary(decimal):
    binary = bin(int(decimal))[2:]
    if '.' in str(decimal):
        fractional_part = str(decimal).split('.')[1]
        binary_fractional = ''
        for digit in fractional_part:
            binary_fractional += bin(int(digit))[2:]
        binary += '.' + binary_fractional
    return 'db' + binary + 'db'

